// -- Rc-wrapped container operations (FF-8) ---------------------------------
// These mirror the bare Vec/HashMap functions above but operate on Rc-wrapped
// containers for O(1) clone cost. Generated code using Rc container templates
// will call these. Read-only functions (map_get, map_keys, map_values, lookup,
// map_contains_key, map_has) work with Rc<HashMap> via auto-deref.

// Shared-Rc update guard (operator ruling 2026-07-05): a clone fallback in an
// rc_* update is a degradation arm — it must refuse (fail, the default and the
// only production mode) or be counted and loud (count: the stopped-line audit
// instrument, never a way to keep producing), per DESIGN.md 5. There is no
// silence mode — escape hatches are banned (operator ruling 2026-07-05).
// #[track_caller] threads the generated caller's file:line into the diagnostic
// so each refusal names the exact emitted site to license.
struct RcCloneFallbackLedger(std::cell::RefCell<std::collections::HashMap<String, u64>>);

impl Drop for RcCloneFallbackLedger {
    fn drop(&mut self) {
        let m = self.0.borrow();
        if m.is_empty() {
            return;
        }
        let mut v: Vec<(&String, &u64)> = m.iter().collect();
        v.sort_by(|a, b| b.1.cmp(a.1).then(a.0.cmp(b.0)));
        eprintln!("clone-fallback report: {} sites degraded this run", v.len());
        for (site, n) in v {
            eprintln!("clone-fallback total: {:>12}  {}", n, site);
        }
    }
}

thread_local! {
    static RC_CLONE_FALLBACKS: RcCloneFallbackLedger =
        RcCloneFallbackLedger(std::cell::RefCell::new(std::collections::HashMap::new()));
}

fn clone_fallback_mode() -> u8 {
    static MODE: std::sync::OnceLock<u8> = std::sync::OnceLock::new();
    *MODE.get_or_init(|| match std::env::var("GUNBC_CLONE_FALLBACK").as_deref() {
        Ok("count") => 1,
        _ => 2,
    })
}

#[track_caller]
fn rc_shared_update_guard(op: &str, strong: usize) {
    match clone_fallback_mode() {
        1 => {
            let key = format!("{} at {}", op, std::panic::Location::caller());
            RC_CLONE_FALLBACKS.with(|m| {
                let mut m = m.0.borrow_mut();
                let n = m.entry(key.clone()).or_insert(0);
                *n += 1;
                if *n == 1 {
                    eprintln!("clone-fallback (count): {}", key);
                }
            });
        }
        _ => panic!(
            "clone-fallback refused: {} at {} on a shared Rc (strong={}) — this update \
             deep-copies the whole container. Last use? -> missing move license \
             (emitter site). Genuinely still live? -> the copy needs structural \
             sharing, not a clone. GUNBC_CLONE_FALLBACK=count runs the stopped-line \
             audit (full ledger, still not a green run).",
            op,
            std::panic::Location::caller(),
            strong
        ),
    }
}

pub fn rc_clone_fallback_counts() -> Vec<(String, u64)> {
    RC_CLONE_FALLBACKS.with(|m| {
        let mut v: Vec<(String, u64)> = m.0.borrow().iter().map(|(k, n)| (k.clone(), *n)).collect();
        v.sort();
        v
    })
}

#[track_caller]
pub fn rc_list_push<T: Clone>(list: Rc<Vec<T>>, item: T) -> Rc<Vec<T>> {
    let mut v = list;
    if Rc::strong_count(&v) > 1 {
        rc_shared_update_guard("rc_list_push", Rc::strong_count(&v));
    }
    Rc::make_mut(&mut v).push(item);
    v
}

#[track_caller]
pub fn rc_list_concat<T: Clone>(a: Rc<Vec<T>>, b: Rc<Vec<T>>) -> Rc<Vec<T>> {
    let mut result = a;
    if Rc::strong_count(&result) > 1 {
        rc_shared_update_guard("rc_list_concat", Rc::strong_count(&result));
    }
    Rc::make_mut(&mut result).extend(b.iter().cloned());
    result
}

// Map updates carry no shared-Rc guard: HashMap here is im_rc's persistent
// HAMT (one realization with the interpreter's Value::Map), so make_mut's
// clone arm is O(1) structural sharing and each insert copies an O(log n)
// node path — a designed update, not a degradation arm. Lists/sets above
// remain O(n)-copy carriers and keep the guard until they migrate too.
pub fn rc_map_insert<K: std::cmp::Eq + std::hash::Hash + Clone, V: Clone>(
    map: Rc<HashMap<K, V>>,
    key: K,
    value: V,
) -> Rc<HashMap<K, V>> {
    let mut m = map;
    Rc::make_mut(&mut m).insert(key, value);
    m
}

pub fn rc_map_merge<K: std::cmp::Eq + std::hash::Hash + Clone, V: Clone>(
    base: Rc<HashMap<K, V>>,
    overlay: Rc<HashMap<K, V>>,
) -> Rc<HashMap<K, V>> {
    let mut result = base;
    let inner = Rc::make_mut(&mut result);
    for (k, v) in overlay.iter() {
        inner.insert(k.clone(), v.clone());
    }
    result
}

pub fn rc_index_by<V: Clone, F: Fn(&V) -> String>(
    list: Rc<Vec<V>>,
    key_fn: F,
) -> Rc<HashMap<String, V>> {
    Rc::new(list.iter().map(|v| (key_fn(v), v.clone())).collect())
}

pub fn rc_empty_map<K: std::cmp::Eq + std::hash::Hash, V>() -> Rc<HashMap<K, V>> {
    Rc::new(HashMap::new())
}

impl<T: Clone> V2Concat for Rc<Vec<T>> {
    fn v1_concat(self, other: Rc<Vec<T>>) -> Rc<Vec<T>> {
        rc_list_concat(self, other)
    }
}

pub fn scan_while(s: &str, start: i64, pred: impl Fn(String) -> bool) -> i64 {
    let start = start.max(0) as usize;
    if s.is_ascii() {
        let bytes = s.as_bytes();
        let mut pos = start.min(bytes.len());
        while pos < bytes.len() && pred(String::from(bytes[pos] as char)) {
            pos += 1;
        }
        return pos as i64;
    }
    let char_len = s.chars().count();
    let start = start.min(char_len);
    let mut pos = start;
    for ch in s.chars().skip(start) {
        if pred(ch.to_string()) {
            pos += 1;
        } else {
            break;
        }
    }
    pos as i64
}

pub fn skip_horizontal_ws(s: &str, start: i64) -> i64 {
    let start = start.max(0) as usize;
    if s.is_ascii() {
        let bytes = s.as_bytes();
        let mut pos = start.min(bytes.len());
        while pos < bytes.len() && (bytes[pos] == b' ' || bytes[pos] == b'\t') {
            pos += 1;
        }
        return pos as i64;
    }
    let char_len = s.chars().count();
    let start = start.min(char_len);
    let mut pos = start;
    for ch in s.chars().skip(start) {
        if ch == ' ' || ch == '\t' {
            pos += 1;
        } else {
            break;
        }
    }
    pos as i64
}

pub fn scan_to_eol(s: &str, start: i64) -> i64 {
    let start = start.max(0) as usize;
    if s.is_ascii() {
        let bytes = s.as_bytes();
        let start = start.min(bytes.len());
        for i in start..bytes.len() {
            if bytes[i] == b'\n' {
                return i as i64;
            }
        }
        return bytes.len() as i64;
    }
    let char_len = s.chars().count();
    let start = start.min(char_len);
    let mut pos = start;
    for ch in s.chars().skip(start) {
        if ch == '\n' {
            return pos as i64;
        }
        pos += 1;
    }
    pos as i64
}

pub fn scan_string_end(s: &str, start: i64) -> i64 {
    let start = start.max(0) as usize;
    if s.is_ascii() {
        let bytes = s.as_bytes();
        let mut pos = start.min(bytes.len());
        while pos < bytes.len() {
            if bytes[pos] == b'\\' {
                pos += 2;
            } else if bytes[pos] == b'\"' {
                return (pos + 1) as i64;
            } else {
                pos += 1;
            }
        }
        return bytes.len() as i64;
    }
    let char_len = s.chars().count();
    let start = start.min(char_len);
    let mut pos = start;
    let mut escaped = false;
    for ch in s.chars().skip(start) {
        if escaped {
            escaped = false;
            pos += 1;
        } else if ch == '\\' {
            escaped = true;
            pos += 1;
        } else if ch == '\"' {
            return (pos + 1) as i64;
        } else {
            pos += 1;
        }
    }
    pos as i64
}

