pub fn is_emoji_ident(cp: i64) -> bool {
    use unicode_properties::emoji::EmojiStatus;
    use unicode_properties::emoji::UnicodeEmoji;
    char::from_u32(cp as u32)
        .map(|c| {
            matches!(
                c.emoji_status(),
                EmojiStatus::EmojiPresentation
                    | EmojiStatus::EmojiPresentationAndModifierBase
                    | EmojiStatus::EmojiPresentationAndEmojiComponent
                    | EmojiStatus::EmojiPresentationAndModifierAndEmojiComponent
            ) && !unicode_ident::is_xid_continue(c)
        })
        .unwrap_or(false)
}

const FNV1A64_OFFSET: u64 = 0xcbf29ce484222325;
const FNV1A64_PRIME: u64 = 0x100000001b3;

fn fnv1a64(bytes: &[u8]) -> u64 {
    let mut hash = FNV1A64_OFFSET;
    for b in bytes {
        hash ^= *b as u64;
        hash = hash.wrapping_mul(FNV1A64_PRIME);
    }
    hash
}

pub type Hash = String;

const HASH_DIGEST_LEN: usize = 16;

pub fn is_hash_digest(s: &str) -> bool {
    s.len() == HASH_DIGEST_LEN && s.bytes().all(|b| b.is_ascii_hexdigit())
}

fn expect_hash_digest(s: &str, arg: &str) {
    if !is_hash_digest(s) {
        panic!("{} must be a 16-char hex Hash digest", arg);
    }
}

/// Stage-boundary trace mark — the v1-seed interim realization of the v2 per-RealizedStep
/// CostAccount (std.realization_measurement). One stderr line per mark; consecutive marks
/// define the segments of a natural Gantt read directly off any run log.
///
/// **Dissolution trigger (DESIGN §6):** delete this fn, the `trace_mark` registry row in
/// `04_method.dag` (+ hand-synced twin `v1_compiler_infer_method.rs`), the nine
/// `trace_mark(...)` marks in `compile.dag` (+ hand-synced `v1_compiler_compile.rs`), and
/// the interpreter arm in `v1_interpreter.rs` when realization_measurement_loop **Phase 0**
/// (`docs/plans/realization-measurement-loop.md`) lands a `.dag` `PerformanceReceipt`
/// per-stage carrier that a floor witness consumes by execution (the same retirement event
/// as `phase_profile.rs` / `GUNBC_FLOOR_GANTT`, per `docs/plans/ci-floor-fractal-gantt.md`
/// § dissolution). Receipt = that witness green with these marks deleted and stage walls
/// still attributable from the model path.
pub fn trace_mark(label: String) {
    use std::sync::OnceLock;
    use std::time::Instant;
    static TRACE_T0: OnceLock<Instant> = OnceLock::new();
    let ms = TRACE_T0.get_or_init(Instant::now).elapsed().as_millis();
    let mut rss_mib = String::from("absent");
    if let Ok(status) = std::fs::read_to_string("/proc/self/status") {
        for line in status.lines() {
            if let Some(rest) = line.strip_prefix("VmRSS:") {
                if let Some(kib) = rest
                    .split_whitespace()
                    .next()
                    .and_then(|k| k.parse::<i64>().ok())
                {
                    rss_mib = (kib / 1024).to_string();
                }
            }
        }
    }
    eprintln!("[gantt] {} t_ms={} rss_mib={}", label, ms, rss_mib);
}

/// Content hash over raw bytes — the byte-level single authority. `atom_identity_hash`
/// is the `String` projection of this. Use this directly for arbitrary binary content
/// (e.g. an executable or serialized payload): routing bytes through `String`/
/// `from_utf8_lossy` first collapses every invalid UTF-8 sequence to U+FFFD, so distinct
/// byte sequences would hash equal — a §5 silent-collision fail-open for content-addressing.
pub fn bytes_identity_hash(bytes: &[u8]) -> Hash {
    format!("{:016x}", fnv1a64(bytes))
}

pub fn atom_identity_hash(s: String) -> Hash {
    bytes_identity_hash(s.as_bytes())
}

pub fn hash_combine(a: Hash, b: Hash) -> Hash {
    expect_hash_digest(&a, "a");
    expect_hash_digest(&b, "b");
    let mut bytes = a.into_bytes();
    bytes.push(0);
    bytes.extend_from_slice(b.as_bytes());
    format!("{:016x}", fnv1a64(&bytes))
}

#[derive(Debug, Clone)]
pub struct FilesystemReadResult {
    pub content: String,
}

pub fn filesystem_read(path: String) -> FilesystemReadResult {
    let content =
        std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("failed to read {}: {}", path, e));
    FilesystemReadResult { content }
}
fn int_relu(x: i64) -> i64 {
    if x > 0 {
        x
    } else {
        0
    }
}

/// Opcode wire authority: `extdeps.languages.simd.kernel.relu_mul_add_wire_op_codes`.
/// Scaffold regen-sync: see `host_kernel_relu_mul_add_op_codes_scaffold_note` until feature:dag-kernel-realization-handler.
const RELU_MUL_ADD_OP_CODES: [i64; 3] = [1, 2, 3];

fn assert_relu_mul_add_op_codes(op_codes: &[i64], _handler: &str) {
    if op_codes != RELU_MUL_ADD_OP_CODES {
        panic!("unsupported op_codes in accelerator demo kernel");
    }
}

/// Host bridge: `.dag` passes `std.numerical_contract.FmaContractionPolicy`; interpreter maps to 0/1 until target_model emit.
pub fn contiguous_loop_elementwise_float_kernel(
    op_codes: &[i64],
    fma_contraction_policy: i64,
    a: &[f64],
    b: &[f64],
    c: &[f64],
) -> Vec<f64> {
    assert_relu_mul_add_op_codes(op_codes, "contiguous_loop_elementwise_float_kernel");
    assert_eq!(a.len(), b.len());
    assert_eq!(b.len(), c.len());
    let mut out = Vec::with_capacity(a.len());
    for i in 0..a.len() {
        let elem = match fma_contraction_policy {
            0 => {
                let prod = a[i] * b[i];
                prod + c[i]
            }
            1 => a[i].mul_add(b[i], c[i]),
            _ => panic!("unknown fma_contraction_policy"),
        };
        out.push(if elem > 0.0 { elem } else { 0.0 });
    }
    out
}

/// Integer oracle authority: `gunbc.accelerator_demo_eval` via interpreter `Int` binops (`*`/`+`).
/// Host kernel uses `wrapping_*` to mirror release interpreter overflow semantics; demo fixtures
/// stay in-range under `IntegerExact` — out-of-range inputs are outside the bit-exact bar.
pub fn contiguous_loop_elementwise_kernel(
    op_codes: &[i64],
    a: &[i64],
    b: &[i64],
    c: &[i64],
) -> Vec<i64> {
    assert_relu_mul_add_op_codes(op_codes, "contiguous_loop_elementwise_kernel");
    assert_eq!(a.len(), b.len());
    assert_eq!(b.len(), c.len());
    let mut out = Vec::with_capacity(a.len());
    for i in 0..a.len() {
        let tmp = a[i].wrapping_mul(b[i]).wrapping_add(c[i]);
        out.push(int_relu(tmp));
    }
    out
}

// take_owned_counted: the fail-closed replacement for the silent
// `Rc::try_unwrap(x).unwrap_or_else(|rc| (*rc).clone())` fallback (DESIGN.md §5:
// a failure arm must refuse or be counted, never silently widen). The ownership
// proof licenses the take-owned; a shared Rc at runtime is a proof deficit whose
// per-site frequency must stay observable, so the clone arm counts per emitted
// site (site = "<module>:<span_start>" of the use-site the emitter rewrote).
thread_local! {
    static TAKE_OWNED_CLONE_FALLBACKS: std::cell::RefCell<std::collections::HashMap<&'static str, u64>> =
        std::cell::RefCell::new(std::collections::HashMap::new());
}

/// INVARIANT: `site` must be a string literal (the emitter always passes one).
/// Counts key on `&'static str`; a non-literal static with duplicate content
/// could fragment one site's count across entries and silently degrade the
/// per-site observability this function exists to provide (DESIGN.md 5).
pub fn take_owned_counted<T: Clone>(x: Rc<T>, site: &'static str) -> T {
    Rc::try_unwrap(x).unwrap_or_else(|rc| {
        if clone_fallback_mode() == 2 {
            panic!(
                "clone-fallback refused: take_owned at emitted site {} on a shared Rc \
                 (strong={}) — the licensed move found the value still shared. \
                 GUNBC_CLONE_FALLBACK=count runs the stopped-line audit.",
                site,
                Rc::strong_count(&rc)
            );
        }
        TAKE_OWNED_CLONE_FALLBACKS.with(|m| *m.borrow_mut().entry(site).or_insert(0) += 1);
        let key = format!("take_owned at {}", site);
        RC_CLONE_FALLBACKS.with(|m| {
            let mut m = m.0.borrow_mut();
            let n = m.entry(key.clone()).or_insert(0);
            *n += 1;
            if *n == 1 {
                eprintln!("clone-fallback (count): {}", key);
            }
        });
        (*rc).clone()
    })
}

pub fn take_owned_clone_fallback_counts() -> Vec<(String, u64)> {
    TAKE_OWNED_CLONE_FALLBACKS.with(|m| {
        let mut v: Vec<(String, u64)> = m
            .borrow()
            .iter()
            .map(|(site, n)| (site.to_string(), *n))
            .collect();
        v.sort();
        v
    })
}

pub fn reset_take_owned_clone_fallbacks() {
    TAKE_OWNED_CLONE_FALLBACKS.with(|m| m.borrow_mut().clear());
}
